insert into words (deck_id, term, translation, "order", image_url)
select d.id, v.t, v.tr, v.o, case when v.k = '' then null else (
  select x.image_url from words x join word_decks xd on xd.id = x.deck_id and xd.deleted_at is null
  where x.image_url is not null and lower(trim(x.term)) = lower(trim(v.t))
    and (v.k = 's' or (select coalesce(array_agg(distinct left(w,4)),'{}') from regexp_split_to_table(replace(lower(coalesce(x.translation,'')),'ё','е'), '[^а-я]+') w
  where length(w)>=3 and w not in ('что','кто','кого','чем','чего','либо','нибудь','себя','свой','быть','очень','такой','этот','который')) && (select coalesce(array_agg(distinct left(w,4)),'{}') from regexp_split_to_table(replace(lower(coalesce(v.tr,'')),'ё','е'), '[^а-я]+') w
  where length(w)>=3 and w not in ('что','кто','кого','чем','чего','либо','нибудь','себя','свой','быть','очень','такой','этот','который')))
  order by x.id desc limit 1) end
